// === Tab: mySketch ===
// Ecrit par Jycer
// https://openprocessing.org/user/260656/
let resolution = 7;
let radius = 60;
let blur = 0;
let nbCell = 25;
let flou=true;
let cells=[];
let focal=0;
const drawPoint=false;

function setup() {
	createCanvas(windowWidth, windowHeight);
	angleMode(DEGREES);
	textAlign(CENTER,CENTER);
	ctx = canvas.getContext('2d');

	for( let i=0;i<nbCell;i++){
		cells[i] = new Cell(i);
	}
}

function draw() {
	background(255,255);

	if(random()>.99)flou=true;
	if(flou) blur = -int(sin(focal++)*20);                                                                                                                                                                                                        	                                                                                                                                                                                                                                  if(blur>=0) ctx.filter = 'blur('+blur+'px)';
	if(blur==0)flou=false;

	for( let i=0;i<nbCell;i++){
		cells[i].interaction(cells);
		cells[i].move();
		cells[i].draw();
	}
}

function mousePressed() {	fullscreen( !fullscreen() ); }
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}
/**************************************\
					  CLASS CELL
\**************************************/
class Cell{
	constructor(index){
		this.index = index;
		this.pos = createVector( random(radius, width - radius), random(radius, height - radius)) ;
		this.target = createVector( random(radius, width - radius), random(radius, height - radius)) ;
		this.vit = createVector(0,0);
		this.angle = random(360) ;
		this.noiseSal = index;
		this.life = 10000;
		this.skin=[];
		this.r=[];
		let pas = 360/resolution;
		for (let i = 0; i < resolution; i++) {
			this.r[i] = random(radius/2,radius);
			this.skin[i] = createVector( cos(pas * i) * this.r[i]  , sin(pas * i) * this.r[i] );
		}
	}

	/*****************DRAW*****************/
	draw(){
		// visualize target
		noStroke(); fill(0, 255, 0); ellipse(this.target.x, this.target.y, (radius*0.2));
		if(this.life<1000) {
			textSize(radius*0.50); fill(0);noStroke();text(this.life,this.target.x , this.target.y);
		}

		push();
		// Vecteur target
		if(drawPoint){ stroke(255,0,0); strokeWeight(1); line(this.pos.x, this.pos.y, this.target.x, this.target.y );}

		// Vecteur vitesse
		if(drawPoint){ stroke(0); strokeWeight(3); fill(255,0,0); line(this.pos.x, this.pos.y, this.pos.x+this.vit.x*(radius*0.2), this.pos.y+this.vit.y*(radius*0.2) );}

		// visualize drawPoint
		translate( this.pos.x, this.pos.y );
		rotate( this.angle );
		if(drawPoint){
			textSize(radius*0.10);
			for (let j = 0; j < resolution; j++) {
				fill(0,0,255);
				circle(this.skin[j].x , this.skin[j].y ,radius*0.1);
				fill(255);
				text(j,this.skin[j].x , this.skin[j].y);
			}
			noFill();stroke(0); strokeWeight(0.1); circle(0,0,radius*2);
			textSize(radius*0.50); fill(0);noStroke();text(this.life,this.skin[0].x , this.skin[0].y);
		}

		// visualize skin
		stroke(12,20);
		strokeWeight(radius*.1);
		fill(120,120,0,50);
		beginShape();
		curveVertex(this.skin[resolution-1 ].x , this.skin[resolution-1 ].y );
		for (let i = 0; i < resolution; i++) {
			curveVertex(this.skin[i].x , this.skin[i].y);
		}
		curveVertex(this.skin[0].x , this.skin[0].y);
		curveVertex(this.skin[1].x , this.skin[1].y);
		endShape( );

		// Visualize noyau
		circle(0 , 0 ,radius*0.5);
		if(drawPoint){
			noStroke(); fill(0); circle(0,0,(radius*0.10));
			noStroke();	fill(255);	text(this.index, 0, 0);
		}

		pop();
	}

	/****************MOVE***************/
	move(){
		this.pos.add(this.vit);
		//this.vit.mult(0.9);
		var pas = 360/resolution;
		for (let i = 0; i < resolution; i++) {
			this.noiseSal+=0.001;
			this.r[i] = (0.5-noise(this.noiseSal+i))*(radius*0.9) + radius;
			this.skin[i] = createVector( cos(pas * i) * this.r[i]  , sin(pas * i) * this.r[i] );
		}
		this.life--;
	}

	/*****************INTERACTION*****************/
	interaction(cells){
		let dist = this.pos.dist(this.target);
		if( dist<radius*0.25 || this.life<0) {
			this.life = 10000;
			this.target = createVector( random(radius, width - radius), random(radius, height - radius)) ;
		}
		let attraction = this.target.copy().sub(this.pos).normalize().mult(dist<1000?1/dist:dist/1000); // 0.05);
		this.vit.add(attraction).normalize();
		//this.vit = this.target.copy().sub(this.pos).normalize();
		//this.vit = this.target.normalize().mult(20);
		//this.vit.rotate(10)
/*		for(let i=0; i<cells.length; i++){
			if(i!=this.index && 
				this.pos.dist(cells[i].pos)<radius*2){
					//print( this.index+" touche "+ i);
			}
		}*/
	}
}

